contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Concrete scenario: single recipient, amount 1 (ether unit)
        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);
        uint[] memory values = new uint[](1);
        values[0] = 1;

        // The only authorized caller is 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);

        // Try the call and capture whether it succeeds or reverts
        bool ok;
        try c.transfer(tos, values) {
