pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple ERC20-like receiver that tracks balance
        // But we can't deploy extra contracts – instead, we'll use an account
        // Prepare recipient address
        address recipient = address(0xBEEF);
        address[] memory tos = new address[](1);
        tos[0] = recipient;
        uint[] memory amounts = new uint[](1);
        amounts[0] = 1; // 1 wei token, not ETH

        // The reference contract's internal transferFrom(address(0x9797...), recipient, 1e18) succeeds
        // The mutant's transferFrom(address(0), recipient, 1e18) will fail because address(0) can't transferFrom
        // So the call reverts on mutant, succeeds on reference

        // First test the reference (in real usage, we deploy the correct one)
        // Here we have only one deployment – so we test the deployed contract
        // Since the test is run twice (once with reference, once with mutant), we just assert
        // that the call does NOT revert (reference behavior)
        // But we need a concrete assertion that fails on mutant

        // Instead: check that after the call, the from address remains unchanged
        // This assertion passes on both but we need divergence

        // Better approach: check that the call succeeds on reference and fails on mutant
        // We'll test this as a revert boolean

        // Use try-catch to capture revert
        bool success;
        try c.transfer(tos, amounts) {
            success = true;
        } catch {
            success = false;
        }

        // On the reference contract, this call succeeds because the 'from' (0x9797...) can be transferred from
        // On the mutant, transferFrom from address(0) will revert (0x cannot transferFrom)
        // The assertion "success == true" passes on reference, fails on mutant
        assertTrue(success);
    }
}

